// Dipanggil tiap ada data dari MQTT iot/sensor
const data = msg.payload;
data.received = new Date().toISOString();
flow.set('lastSensor', data);

// Cek threshold
let threshold = flow.get('threshold');
if (typeof threshold !== 'number') threshold = 30;   // default 30 C

const over = data.suhu > threshold;
const wasOver = flow.get('alertActive') === true;
flow.set('alertActive', over);

// Output 1 -> simpan ke SQLite
const dbMsg = { params: {
    $suhu: data.suhu,
    $kelembaban: data.kelembaban,
    $timestamp: data.timestamp,
    $received: data.received
}};

// Output 2 -> broadcast ke WebSocket
const wsMsg = { payload: { type: 'sensor', data: data, threshold: threshold, alert: over } };

// Output 3 -> notifikasi, hanya saat suhu BARU SAJA melewati batas (tidak spam)
let alertMsg = null;
if (over && !wasOver) {
    alertMsg = {
        topic: 'iot/alert',
        payload: {
            type: 'alert',
            level: 'warning',
            message: 'Suhu ' + data.suhu + ' C melewati batas ' + threshold + ' C',
            suhu: data.suhu,
            threshold: threshold,
            timestamp: data.received
        }
    };
    node.warn(alertMsg.payload.message);
}
return [dbMsg, wsMsg, alertMsg];

// Gerbang autentikasi: cek header X-API-Key
const API_KEY = env.get('API_KEY') || 'iot-kampus-123';
const key = msg.req.headers['x-api-key'];

// route key = METHOD + path, dipakai oleh node switch
msg.route = msg.req.method + ' ' + msg.req.path.replace(/\/+$/, '');

if (key !== API_KEY) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'API key tidak valid atau tidak ada (header X-API-Key)' };
    return [null, msg];
}
return [msg, null];

const data = flow.get('lastSensor') || { suhu: null, kelembaban: null, timestamp: null };
msg.payload = { status: 'success', data: data, server_time: new Date().toISOString() };
return msg;

// Ambil 50 data terakhir dari SQLite
msg.topic = "SELECT suhu, kelembaban, timestamp, received FROM sensor_history ORDER BY id DESC LIMIT 50;";
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
rows.reverse();   // urutan lama -> baru, sama seperti versi modul
msg.payload = { status: 'success', count: rows.length, data: rows };
return msg;

const body = msg.payload || {};
if (!body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'device dan action wajib diisi' };
    return [msg, null];
}
const mqttMsg = { topic: 'iot/kontrol', payload: body };
msg.statusCode = 200;
msg.payload = { status: 'success', message: 'Perintah terkirim', sent: body };
return [msg, mqttMsg];

let t = flow.get('threshold');
if (typeof t !== 'number') t = 30;
msg.payload = { status: 'success', threshold: t };
return msg;

const body = msg.payload || {};
const value = Number(body.threshold);
if (body.threshold === undefined || body.threshold === null || body.threshold === '' || !isFinite(value)) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Field "threshold" wajib berupa angka, contoh: {"threshold": 30}' };
    return [msg, null];
}
flow.set('threshold', value);
flow.set('alertActive', false);   // reset supaya alert bisa muncul lagi
msg.statusCode = 200;
msg.payload = { status: 'success', message: 'Threshold diperbarui', threshold: value };
const wsMsg = { payload: { type: 'threshold', threshold: value } };
return [msg, wsMsg];

// Semua response lewat sini: pasang CORS + status default
msg.statusCode = msg.statusCode || 200;
msg.headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;
